if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_go_build_pgo() {
    printf '%s\n' auto off
    _argc_util_comp_path
}

_choice_go_buildmode() {
    printf '%s\n' archive c-archive c-shared default exe pie plugin shared
}

_choice_go_env_var() {
    go env -json 2>/dev/null | jq -b -r 'to_entries[] | "\(.key)\t\(.value)"'
}

_choice_go_exec() {
    _argc_util_comp_command
}

_choice_go_mod_edit() {
    local query
    case "${argc__option:-}" in
    argc_droprequire) query='.Require[]?.Path' ;;
    argc_dropexclude) query='.Exclude[]? | "\(.Path)@\(.Version)"' ;;
    argc_dropreplace) query='.Replace[]? | "\(.Old.Path + (if .Old.Version then "@" + .Old.Version else "" end))\t\(.New.Path)"' ;;
    argc_droptool) query='.Tool[]?.Path' ;;
    argc_dropignore) query='.Ignore[]?.Path' ;;
    argc_dropgodebug) query='.GoDebug[]?.Key' ;;
    *) return 0 ;;
    esac
    _helper_go_mod_json | jq -b -r "$query"
}

_choice_go_mod_replace() {
    _argc_util_mode_kv =
    if [[ -z "$argc__kv_prefix" ]]; then
        _helper_go_mod_require_paths | _argc_util_transform suffix== nospace
    else
        _argc_util_comp_path cd="$(_helper_go_mod_root)" filter="$argc__kv_filter"
    fi
}

_choice_go_mod_why() {
    _argc_util_parallel _helper_go_mod_require_paths ::: _helper_go_list_imports
}

_choice_go_tool_command() {
    go tool 2>/dev/null
}

_choice_go_work_edit() {
    local query
    case "${argc__option:-}" in
    argc_dropuse) query='.Use[]?.DiskPath' ;;
    argc_dropreplace) query='.Replace[]? | "\(.Old.Path + (if .Old.Version then "@" + .Old.Version else "" end))\t\(.New.Path)"' ;;
    argc_dropgodebug) query='.Godebug[]?.Key' ;;
    *) return 0 ;;
    esac
    _helper_go_work_json | jq -b -r "$query"
}

_choice_go_work_replace() {
    local root dir disk_path
    root="$(_helper_go_work_root)"
    [[ -n "$root" ]] || return 0
    _argc_util_mode_kv =
    if [[ -z "$argc__kv_prefix" ]]; then
        while IFS= read -r disk_path; do
            if [[ "$disk_path" == /* ]]; then
                dir="$disk_path"
            else
                dir="$(_argc_util_path_resolve "$root" "$disk_path")"
            fi
            (cd "$dir" 2>/dev/null && go mod edit -json 2>/dev/null | jq -b -r '.Require[]?.Path')
        done < <(_helper_go_work_json | jq -b -r '.Use[]?.DiskPath') | _argc_util_transform suffix== nospace
    else
        _argc_util_comp_path cd="$root" filter="$argc__kv_filter"
    fi
}

_helper_go_list_imports() {
    go list -f '{{.ImportPath}}{{printf "\t"}}{{.Doc}}' all 2>/dev/null
}

_helper_go_mod_json() {
    if [[ -n "${argc_go_mod:-}" && -f "$argc_go_mod" ]]; then
        go mod edit -json "$argc_go_mod" 2>/dev/null
    else
        go mod edit -json 2>/dev/null
    fi
}

_helper_go_mod_require_paths() {
    _helper_go_mod_json | jq -b -r '.Require[]?.Path'
}

_helper_go_mod_root() {
    if [[ -n "${argc_go_mod:-}" && -f "$argc_go_mod" ]]; then
        dirname "$argc_go_mod"
        return 0
    fi
    _argc_util_path_search_parent -p go.mod
}

_helper_go_work_json() {
    if [[ -n "${argc_go_work:-}" && -f "$argc_go_work" ]]; then
        go work edit -json "$argc_go_work" 2>/dev/null
    else
        go work edit -json 2>/dev/null
    fi
}

_helper_go_work_root() {
    if [[ -n "${argc_go_work:-}" && -f "$argc_go_work" ]]; then
        dirname "$argc_go_work"
        return 0
    fi
    _argc_util_path_search_parent -p go.work
}
